/**
 * UC-002: View Veterinarians.
 *
 * Displays veterinarians and their specialties in a lazily loaded grid.
 */
@Route(value = "vets", layout = MainLayout.class)
@PageTitle("Veterinarians")
public class VeterinariansView extends VerticalLayout {

    private transient VetRepository vetRepository;

    public VeterinariansView(VetRepository vetRepository) {
        this.vetRepository = vetRepository;

        H2 heading = new H2("Veterinarians");
        heading.addClassNames(LumoUtility.Margin.NONE);

        Grid<Veterinarian> veterinariansGrid = new Grid<>(Veterinarian.class, false);
        veterinariansGrid.addColumn(Veterinarian::firstName).setHeader("First Name");
        veterinariansGrid.addColumn(Veterinarian::lastName).setHeader("Last Name");
        veterinariansGrid.addColumn(veterinarian -> veterinarian.specialties().isEmpty()
                        ? "none"
                        : String.join(", ", veterinarian.specialties()))
                .setHeader("Specialties");
        veterinariansGrid.setWidthFull();
        veterinariansGrid.setItems(
                query -> this.vetRepository.findPage(query.getOffset(), query.getLimit()),
                query -> this.vetRepository.count());

        setSizeFull();
        addClassNames(LumoUtility.Padding.MEDIUM);
        setFlexGrow(1, veterinariansGrid);
        add(heading, veterinariansGrid);
    }
}

